namespace ghidra.framework.plugintool.util;





using ghidra;
using ghidra.util;
using ghidra.util.classfinder;
using ghidra.util.classfinder;

public abstract class PluginPackage : ExtensionPoint, Comparable<PluginPackage> {
	public static readonly int UTILITY_PRIORITY = 0;
	public static readonly int CORE_PRIORITY = 1;
	public static readonly int FEATURE_PRIORITY = 4;
	public static readonly int MISCELLANIOUS_PRIORITY = 6;
	public static readonly int DEVELOPER_PRIORITY = 8;
	public static readonly int EXAMPLES_PRIORITY = 10;
	public static readonly int EXPERIMENTAL_PRIORITY = 12;

	private static Map<string, PluginPackage> packageMap;

	/**
	 * Returns true if the system has found a plugin package for the given name
	 * @param packageName the package name
	 * @return true if the system has found a plugin package for the given name
	 */
	public static bool exists(string packageName) {
		if (packageMap == null) {
			packageMap = createPackageMap();
		}
		PluginPackage pluginPackage = packageMap.get(packageName.toLowerCase());
		return pluginPackage != null;
	}

	/**
	 * Returns the existing plugin package with the given name.  If no package exists, then the
	 * {@link MiscellaneousPluginPackage} will be returned.
	 * @param packageName the package name
	 * @return the package
	 */
	public static PluginPackage getPluginPackage(string packageName) {
		if (packageMap == null) {
			packageMap = createPackageMap();
		}
		PluginPackage pluginPackage = packageMap.get(packageName.toLowerCase());
		if (pluginPackage == null) {
			Msg.warn(typeof(PluginPackage),
				"Can't find plugin package for " + packageName + "! Creating stub...");
			pluginPackage = packageMap.get(MiscellaneousPluginPackage.NAME.toLowerCase());
		}
		return pluginPackage;
	}

	private static Map<string, PluginPackage> createPackageMap() {
		Map<string, PluginPackage> map = new();
		List<Class<PluginPackage>> classes =
			ClassSearcher.getClasses(typeof(PluginPackage));
		foreach (Class<PluginPackage> class1 in classes) {
			PluginPackage pluginPackage;
			try {
				pluginPackage = class1.newInstance();

				string name = pluginPackage.getName().toLowerCase();
				if (map.containsKey(name)) {
					Msg.error(typeof(PluginPackage), "PluginPackage already exist for name: " + name);
				}
				else {
					map.put(name, pluginPackage);
				}
			}
			catch (Exception e) {
				Msg.error(typeof(PluginPackage), "Could not instantiate " + class1.getName(), e);
			}
		}

		// make sure this is always there (in case it is not discovered)
		map.put(MiscellaneousPluginPackage.NAME.toLowerCase(), new MiscellaneousPluginPackage());

		return map;
	}

	private string name;
	private Icon icon;
	private string description;
	private int priority;

	protected PluginPackage(string name, Icon icon, string description) : this(name, icon, description, FEATURE_PRIORITY)
    {
	}

	protected PluginPackage(string name, Icon icon, string description, int priority) {
		this.name = name;
		this.icon = icon;
		this.description = description;
		this.priority = priority;
	}

	public string getName() {
		return name;
	}

	public Icon getIcon() {
		return icon;
	}

	public string getDescription() {
		return description;
	}

	/**
	 * The minimum level required to activate plugins when the entire package is activated by the
	 * user.
	 * @return the minimum level
	 */
	public PluginStatus getActivationLevel() {
		return PluginStatus.RELEASED;
	}

	/* @Override */
	public int compareTo(PluginPackage other) {
		if (priority == other.priority) {
			return name.compareTo(other.name);
		}
		return priority - other.priority;
	}

	/* @Override */
	public string toString() {
		return name;
	}
}
